do $$
declare v_est uuid; v_uid uuid := gen_random_uuid(); r record;
begin
-- conta do aparelho do salão
values ('00000000-0000-0000-0000-000000000000',v_uid,'authenticated','authenticated','cumbucas@dnbar.app',extensions.crypt('TROCAR_SENHA_FORTE',extensions.gen_salt('bf')),now(),'{"provider":"email","providers":["email"]}','{}',now(),now(),'','','','');
values (gen_random_uuid(),v_uid,v_uid::text,jsonb_build_object('sub',v_uid::text,'email','cumbucas@dnbar.app','email_verified',true),'email',now(),now(),now());
-- equipe (PIN de teste 1234)
for r in select * from (values ('carlos','Carlos','garcom','Garçom',1),('pedro','Pedro','garcom','Garçom',2),('joao','João','garcom','Garçom',3),('bia','Bia','garcom','Garçonete',4),('aline','Aline','garcom','Garçonete',5),('marcela','Marcela','gerente','Gerente',6)) as x(slug,name,role,label,sort) loop
  with s as (insert into public.staff(establishment_id,name,role,role_label,photo_url,portrait_url,sort)
    values (v_est,r.name,r.role,r.label,'img/staff-'||r.slug||'.jpg','img/staffp-'||r.slug||'.jpg',r.sort) returning id)
end loop;
-- mesas
for i in 1..24 loop insert into public.dining_tables(establishment_id,label,area,sort) values (v_est,lpad(i::text,2,'0'),'Salão',i); end loop;
for i in 1..6 loop insert into public.dining_tables(establishment_id,label,area,sort) values (v_est,'V'||i,'Varanda',100+i); end loop;
end $$;
select (select count(*) from public.products) produtos, (select count(*) from public.staff) equipe, (select count(*) from public.dining_tables) mesas;
